<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { AlertTriangle, Bell, Check, PackageSearch, ShoppingBag } from 'lucide-vue-next'; import { useToast } from '../../composables/useToast'; import { useTopbarLayer } from '../../composables/useTopbarLayer'
const router=useRouter(); const {success}=useToast(); const {active,open:openLayer,close}=useTopbarLayer(); const open=computed({get:()=>active.value==='notifications',set:value=>value?openLayer('notifications'):close('notifications')}); const root=ref<HTMLElement|null>(null); const notices=ref([{id:1,title:'低库存预警',description:'Air X Pro 曜石黑仅剩 8 件',time:'5 分钟前',to:'/inventory',read:false,type:'warning'},{id:2,title:'退款申请待审批',description:'订单 #EB202609010846 申请退款 ¥1,299',time:'18 分钟前',to:'/orders/EB202609010846',read:false,type:'order'},{id:3,title:'商品资料审核通过',description:'Voyage 28 英寸旅行箱可以发布',time:'1 小时前',to:'/products',read:true,type:'product'}]); const unread=computed(()=>notices.value.filter(item=>!item.read).length)
function outside(event:MouseEvent){if(root.value&&!root.value.contains(event.target as Node))open.value=false} function key(event:KeyboardEvent){if(event.key==='Escape')open.value=false} function markAll(){notices.value.forEach(item=>item.read=true);success('通知已全部标记为已读')} function go(item:typeof notices.value[number]){item.read=true;open.value=false;router.push(item.to)}
onMounted(()=>{document.addEventListener('click',outside);document.addEventListener('keydown',key)});onBeforeUnmount(()=>{document.removeEventListener('click',outside);document.removeEventListener('keydown',key)})
</script>
<template><div ref="root" class="topbar-popover-wrap"><button class="notification" :class="{active:open}" aria-label="通知" aria-haspopup="dialog" :aria-expanded="open" @click.stop="open=!open"><Bell :size="19"/><i v-if="unread"></i></button><Transition name="topbar-popover"><section v-if="open" class="topbar-popover notification-popover"><header><div><strong>通知中心</strong><span>{{unread?`${unread} 条未读消息`:'全部已读'}}</span></div><button v-if="unread" @click="markAll"><Check :size="14"/>全部已读</button></header><div v-if="notices.length" class="notice-list"><button v-for="item in notices" :key="item.id" :class="{unread:!item.read}" @click="go(item)"><span :data-type="item.type"><AlertTriangle v-if="item.type==='warning'" :size="16"/><ShoppingBag v-else-if="item.type==='order'" :size="16"/><PackageSearch v-else :size="16"/></span><div><b>{{item.title}}</b><p>{{item.description}}</p><small>{{item.time}}</small></div><i v-if="!item.read"></i></button></div><div v-else class="notice-empty"><Bell :size="22"/><strong>暂无通知</strong><p>新的业务提醒会出现在这里。</p></div><footer><button @click="open=false;router.push('/member/profile?tab=notifications')">管理通知偏好</button></footer></section></Transition></div></template>
